<?php $title='Notifications';require __DIR__.'/../layouts/header.php';?><div class="pagehead"><h1>Notifications</h1></div><div class="panel"><?php foreach($rows as $r):?><div class="timeline-item"><strong><?=e($r['title'])?></strong><p><?=e($r['message'])?></p><small><?=e($r['created_at'])?> · <?=e($r['read_at']?'Read':'Unread')?></small></div><?php endforeach;?><?php if(!$rows):?><p class="muted">No notifications.</p><?php endif;?></div><?php require __DIR__.'/../layouts/footer.php';?>
